+
+.pill{
+  display:inline-flex;align-items:center;gap:8px;
+  padding:6px 10px;
+  border-radius:999px;
+  border:1px solid var(--border);
+  background:var(--panel);
+  color:var(--muted);
+  font-weight:650;
+  font-size:12px;
+}
+.dot{width:8px;height:8px;border-radius:999px;background:var(--accent);box-shadow:0 0 0 4px rgba(33,230,193,.12)}
+
+/* Hero */
+.hero{padding:56px 0 26px}
+.hero-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:26px;align-items:start}
+@media (max-width: 920px){.hero-grid{grid-template-columns:1fr;gap:16px}}
+
+.hero h1{font-size:44px;line-height:1.05;margin:12px 0 10px;letter-spacing:-.03em}
+@media (max-width: 520px){.hero h1{font-size:34px}}
+.lead{color:var(--muted);font-size:16px;max-width:68ch}
+.cta-row{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}
+.kbd{font-family:ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;font-size:12px;color:var(--muted);border:1px solid var(--border);background:var(--panel);padding:2px 6px;border-radius:8px}
+
+.hero-card{
+  border:1px solid var(--border);
+  background:linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.03));
+  border-radius:var(--radius);
+  box-shadow:var(--shadow);
+  overflow:hidden;
+}
+.hero-card .inner{padding:16px}
+.hero-card h3{margin:0 0 6px;font-size:14px;color:var(--muted);font-weight:700;text-transform:uppercase;letter-spacing:.08em}
+.hero-card p{margin:0;color:var(--muted)}
+.hero-card .stat-row{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}
+.stat{
+  padding:12px;border-radius:12px;border:1px solid var(--border);
+  background:rgba(13,17,23,.55);
+}
+.stat .k{font-family:ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;font-weight:800;color:var(--text);font-size:14px}
+.stat .v{color:var(--muted-2);font-size:12px;margin-top:6px}
+
+/* Sections */
+.section{padding:22px 0}
+.section h2{margin:0 0 10px;font-size:22px;letter-spacing:-.02em}
+.section p{margin:0 0 14px;color:var(--muted)}
+
+.grid-3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
+@media (max-width: 920px){.grid-3{grid-template-columns:1fr;}}
+.grid-2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
+@media (max-width: 920px){.grid-2{grid-template-columns:1fr;}}
+
+.card{
+  border:1px solid var(--border);
+  border-radius:var(--radius);
+  background:linear-gradient(180deg, rgba(255,255,255,.055), rgba(255,255,255,.028));
+  box-shadow:0 14px 50px rgba(0,0,0,.30);
+  overflow:hidden;
+}
+.card .content{padding:16px}
+.card h3{margin:0 0 6px;font-size:18px;letter-spacing:-.02em}
+.card p{margin:0 0 14px;color:var(--muted)}
+.card .meta{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:10px}
+.badge{
+  display:inline-flex;align-items:center;gap:6px;
+  padding:6px 10px;
+  border-radius:999px;
+  border:1px solid var(--border);
+  background:rgba(13,17,23,.55);
+  color:var(--muted);
+  font-size:12px;
+  font-weight:650;
+}
+.badge .spark{width:10px;height:10px;border-radius:3px;background:linear-gradient(135deg, var(--accent), var(--accent-2))}
+
+.card.card-apps{border-color:rgba(33,230,193,.22)}
+.card.card-apps .badge .spark{background:linear-gradient(135deg, #21e6c1, #22c55e)}
+.card.card-storefronts{border-color:rgba(22,179,255,.22)}
+.card.card-storefronts .badge .spark{background:linear-gradient(135deg, #16b3ff, #60a5fa)}
+.card.card-agents{border-color:rgba(255,204,102,.22)}
+.card.card-agents .badge .spark{background:linear-gradient(135deg, #ffcc66, #fb7185)}
+
+.card a.card-link{display:block;color:inherit;text-decoration:none}
+.card .cta{display:inline-flex;align-items:center;gap:8px;color:var(--text);font-weight:700}
+.card .cta .arrow{color:var(--accent)}
+.card .cta:hover .arrow{transform:translateX(2px)}
+
+/* CLI Setup */
+.cli{
+  border:1px solid var(--border);
+  border-radius:var(--radius);
+  background:linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.025));
+  overflow:hidden;
+}
+.cli-head{padding:16px;border-bottom:1px solid var(--border)}
+.cli-grid{display:grid;grid-template-columns:1fr 1fr;gap:0}
