+
+.code-pane{padding:16px}
+.tabs{display:flex;gap:6px;align-items:center;margin-bottom:10px;flex-wrap:wrap}
+.tab{
+  font-family:ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
+  font-size:12px;
+  border:1px solid var(--border);
+  background:transparent;
+  color:var(--muted);
+  border-radius:10px;
+  padding:8px 10px;
+  cursor:pointer;
+}
+.tab[aria-selected="true"]{background:var(--panel);color:var(--text);border-color:rgba(33,230,193,.30)}
+.tab:focus{outline:none;box-shadow:var(--focus)}
+
+.codeblock{
+  border:1px solid var(--code-border);
+  background:var(--code-bg);
+  border-radius:14px;
+  overflow:hidden;
+}
+.codeblock .topbar{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 12px;border-bottom:1px solid var(--code-border)}
+.codeblock .title{color:var(--muted);font-weight:700;font-size:12px;letter-spacing:.02em}
+.copy{
+  font-family:ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
+  font-size:12px;
+  padding:8px 10px;
+  border-radius:10px;
+  border:1px solid var(--border);
+  background:transparent;
+  color:var(--muted);
+  cursor:pointer;
+}
+.copy:hover{background:var(--panel);color:var(--text)}
+.copy:focus{outline:none;box-shadow:var(--focus)}
+.codeblock pre{margin:0;padding:12px;overflow:auto}
+.codeblock code{font-family:ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;font-size:13px;color:var(--text)}
+
+/* Docs layout */
+.docs{padding:18px 0 42px}
+.docs-layout{display:grid;grid-template-columns:290px 1fr;gap:18px;align-items:start}
+@media (max-width: 980px){.docs-layout{grid-template-columns:1fr}}
+
+.sidebar{
+  position:sticky;top:84px;
+  border:1px solid var(--border);
+  border-radius:var(--radius);
+  background:linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.02));
+  overflow:hidden;
+}
+@media (max-width: 980px){.sidebar{position:relative;top:0}}
+
+.sidebar-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 12px;border-bottom:1px solid var(--border)}
+.sidebar-title{font-weight:800;letter-spacing:-.02em}
+.sidebar .sidebtn{padding:8px 10px;border-radius:10px}
+.sidebar-nav{padding:10px}
+.sidebar-nav a{
+  display:flex;align-items:center;justify-content:space-between;gap:10px;
+  padding:10px 10px;
+  border-radius:12px;
+  text-decoration:none;
+  color:var(--muted);
+  border:1px solid transparent;
+  font-weight:650;
+}
+.sidebar-nav a:hover{background:var(--panel);color:var(--text)}
+.sidebar-nav a[aria-current="true"]{background:var(--panel);color:var(--text);border-color:var(--border)}
+.sidebar-nav .small{font-size:12px;color:var(--muted-2);font-weight:650}
+
+.docs-layout[data-sidebar="collapsed"]{grid-template-columns:72px 1fr}
+@media (max-width: 980px){.docs-layout[data-sidebar="collapsed"]{grid-template-columns:1fr}}
+.docs-layout[data-sidebar="collapsed"] .sidebar-nav a span.label{display:none}
+.docs-layout[data-sidebar="collapsed"] .sidebar-nav a .small{display:none}
+.docs-layout[data-sidebar="collapsed"] .sidebar{width:72px}
+.docs-layout[data-sidebar="collapsed"] .sidebar-title{display:none}
+.docs-layout[data-sidebar="collapsed"] .sidebar-head{justify-content:center}
+
+.article{
+  border:1px solid var(--border);
+  border-radius:var(--radius);
+  background:linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.02));
+  padding:18px;
+  box-shadow:0 18px 60px rgba(0,0,0,.25);
+}
+.article h1{margin:0 0 8px;font-size:30px;letter-spacing:-.03em}
+.article h2{margin:22px 0 10px;font-size:18px;letter-spacing:-.02em}
+.article p{color:var(--muted);margin:0 0 12px}
+.article ul{margin:0 0 12px;color:var(--muted);padding-left:18px}
+
+.callout{
+  border:1px solid rgba(33,230,193,.25);
+  background:linear-gradient(135deg, rgba(33,230,193,.10), rgba(22,179,255,.06));
+  border-radius:var(--radius);
+  padding:14px;
+  margin:16px 0;
+}
+.callout strong{color:var(--text)}
+
+/* Footer */
+footer{padding:34px 0 46px;border-top:1px solid var(--border);margin-top:24px}
+.footer-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}
+@media (max-width: 920px){.footer-grid{grid-template-columns:repeat(2,minmax(0,1fr));}}
+@media (max-width: 520px){.footer-grid{grid-template-columns:1fr;}}
+.footer-col h4{margin:0 0 10px;font-size:12px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted)}
+.footer-col a{display:block;text-decoration:none;color:var(--muted);padding:6px 0}
+.footer-col a:hover{color:var(--text)}
+.fineprint{margin-top:18px;color:var(--muted-2);font-size:12px}
+
+/* Utilities */
+.divider{height:1px;background:var(--border);margin:18px 0}
+.inline-code{font-family:ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;background:var(--panel);border:1px solid var(--border);padding:2px 6px;border-radius:8px;color:var(--text)}
+
*** End Patch
PATCH

