+
+    if (toggle) {
+      toggle.addEventListener("click", () => {
+        const collapsed = layout.getAttribute("data-sidebar") === "collapsed";
+        setCollapsed(!collapsed);
+      });
+    }
+
+    if (mobileToggle) {
+      mobileToggle.addEventListener("click", () => {
+        const collapsed = layout.getAttribute("data-sidebar") === "collapsed";
+        setCollapsed(!collapsed);
+      });
+    }
+  }
+
